	static BlockSpec parse(String s) {
		int i = s.indexOf('[');
		if (i < 0) {
			return BlockSpec.of(s);
		}
		String[] kv = s.substring(i + 1, s.length() - 1).split("[,=]");
		return BlockSpec.of(s.substring(0, i), kv);
	}

	/** The shell cell at (x, y, z), null = structure void. */
	public static BlockSpec at(int x, int y, int z) {
		char c = ROWS[y * SZ + z].charAt(x);
		return c == ' ' ? null : parse(PALETTE[ALPHABET.indexOf(c)]);
	}

	/** Stamps the shell with its origin at (ox, oy, oz), every block through {@code map} (null result = skip). */
	public static void stamp(Blueprint b, int ox, int oy, int oz, UnaryOperator<BlockSpec> map) {
		for (int y = 0; y < SY; y++) {
			for (int z = 0; z < SZ; z++) {
				for (int x = 0; x < SX; x++) {
					BlockSpec s = at(x, y, z);
					BlockSpec m = s == null ? null : map.apply(s);
					if (m != null && b.inside(ox + x, oy + y, oz + z)) {
						b.set(ox + x, oy + y, oz + z, m);
					}
				}
			}
		}
	}
